const facilities3={factory:{name:'零件工坊',mat:'scrap',period:HOUR,amount:4,icon:'▧'},refinery:{name:'精煉車間',mat:'alloy',period:2*HOUR,amount:2,icon:'⬡'},lab:{name:'晶片研究室',mat:'core',period:4*HOUR,amount:1,icon:'✧'},workshop:{name:'收容技術台',icon:'◉'}};
const originals={render,nav,home,prepare,startRun,startBattle,battleView,endTurn,checkBattle,completeNode,enter,eventView,found,bagHtml,bagSize,capacity,endRun,finishView,collection,archive,validSave,help,sources,confirmImport};
function ensure(){if(!db.world){db.world={version:1,materials:{scrap:0,alloy:0,core:0},balls:{1:6,2:2,3:1},base:{factory:{level:1,last:Date.now()},refinery:{level:1,last:Date.now()},lab:{level:1,last:Date.now()},workshop:{level:1,last:Date.now()}},roster:{amiya:{level:1,copies:1,shards:0},beagle:{level:1,copies:1,shards:0},hibiscus:{level:1,copies:1,shards:0}},seen:{amiya:true,beagle:true,hibiscus:true},companion:'amiya',worker:'beagle',shop:{day:'',bought:{}},pity:{}}}let r=R();if(r&&!r.field){r.field={balls:{1:0,2:0,3:0},cargo:[],materials:{scrap:0,alloy:0,core:0},securedCapture:null,settled:false,companion:db.world.companion};if(r.battle)transformEnemies(r.battle)}}
const W=()=>db.world,F=()=>R()?.field;
function img(id,cls='unit-thumb'){if(id===window.FrontierEnemyTactics?.fragment)return '<img class="'+cls+'" src="assets/planetary-fragment.svg" alt="行星碎屑・星環">';if(units[id]?.kind==='enemy'&&!units[id].asset)return '<span class="'+cls+' enemy-art-fallback" aria-label="'+esc(units[id].name)+'">◇</span>';return `<img data-inspect-actor="${id}" class="${cls}" src="assets/${units[id].image}.png" alt="${units[id].name}" loading="lazy">`}
function materialText(obj){return Object.entries(obj).filter(([k,v])=>mats[k]&&v).map(([k,v])=>mats[k].icon+' '+mats[k].name+' ×'+v).join(' / ')||'無'}
function materialBar(){return `<div class="material-bar">${Object.entries(mats).map(([id,m])=>`<span class="tier-${m.tier}">${m.icon} ${m.name}<b>${W().materials[id]}</b></span>`).join('')}<span>◈ 憑證<b>${db.credits}</b></span></div>`}
function afford(cost,credits=0){return db.credits>=credits&&Object.entries(cost).every(([id,n])=>W().materials[id]>=n)}
function spend(cost,credits=0){if(!afford(cost,credits))return false;for(const[id,n]of Object.entries(cost))W().materials[id]-=n;db.credits-=credits;return true}
function unitProgress(id){let u=W().roster[id];return u?`Lv.${u.level} · 招募/收容 ${u.copies} 次 · 信賴碎片 ${u.shards}`:'未正式入庫'}
function clockText(ms){let sec=Math.max(0,Math.ceil(ms/1000));return `${Math.floor(sec/3600)} 小時 ${Math.floor(sec%3600/60)} 分`}
function dayKey(now=Date.now()){return new Date(now+8*HOUR).toISOString().slice(0,10)}
function syncShop(){let day=dayKey();if(day>W().shop.day){W().shop={day,bought:{}};save()}}
function pending(id,now=Date.now()){let f=W().base[id],d=facilities3[id];if(!d.mat)return{qty:0,ticks:0,remainder:0};let elapsed=Math.max(0,Math.min(tune('offlineHours',48)*HOUR,now-f.last)),ticks=Math.floor(elapsed/d.period),worker=W().roster[W().worker],bonus=worker?Math.floor(worker.level/2):0;return{ticks,qty:ticks*(d.amount*f.level+bonus),remainder:elapsed%d.period}}
window.claimBase=function(options={}){ensure();let now=Date.now(),result=[];for(let[id,d]of Object.entries(facilities3)){if(!d.mat)continue;let p=pending(id,now);if(p.ticks){W().materials[d.mat]+=p.qty;W().base[id].last=now-p.remainder;result.push(d.icon+' '+p.qty)}}save();render();if(!options.silent)toast(result.length?'已收取：'+result.join(' / '):'尚未完成一輪生產。');return result};
function upgradeCost(id){let lv=W().base[id].level;return{cost:{scrap:10*lv,alloy:3*lv,core:lv>=2?lv-1:0},credits:15*lv}}
window.upgradeBase=function(id){if(!facilities3[id]||W().base[id].level>=5)return;let p=upgradeCost(id);if(!afford(p.cost,p.credits)){toast('升級材料不足。');return}claimBase();if(!spend(p.cost,p.credits))return;W().base[id].level++;W().base[id].last=Date.now();save();render();toast('設施已升級。新產能從本次升級後生效。')};
window.craftBall=function(t){let d=devices[t];if(!d)return;if(W().base.workshop.level<t){toast('先升級收容技術台。');return}if(!spend(d.cost,d.credits)){toast('製造材料不足。');return}W().balls[t]++;save();render();toast(d.name+' 製造完成。')};
window.baseView=function(){let total=Object.keys(facilities3).reduce((n,id)=>n+pending(id).qty,0);$('#app').innerHTML=`<div class="eyebrow">RHODES ISLAND / HOME BASE</div><div class="sectionhead"><h1>把遠征，變成日常。</h1><button onclick="go('archive')">後勤與存檔</button></div><p class="muted intro">離線也會生產，最多累積 48 小時。三階材料可以收菜、探索與交易取得；不用守著倒數。時間以此裝置時計算。升級先收取已完成產出，再重啟該設施週期。</p>${materialBar()}<div class="row between base-claim"><span>可收取 ${total} 份材料 · 駐站 ${(units[W().worker]?.name||'未派駐')} Lv.${(W().roster[W().worker]?.level||0)}</span><button class="primary" onclick="claimBase()">一鍵收菜 ↙</button></div><div class="base-grid">${Object.entries(facilities3).map(([id,d])=>{let f=W().base[id],p=pending(id),c=upgradeCost(id);return `<section class="panel facility"><span class="facility-icon">${d.icon}</span><div class="row between"><h3>${d.name}</h3><span class="tag">Lv.${f.level}/5</span></div><p class="muted tiny">${d.mat?`每 ${d.period/HOUR} 小時產出 ${d.amount*f.level+Math.floor((W().roster[W().worker]?.level||0)/2)} 份 ${mats[d.mat].name}<br>已累積 ${p.qty} 份 · 下輪 ${clockText(d.period-p.remainder)}`:`解鎖 T${Math.min(3,f.level)} 裝置，捕獲率加成 ${(f.level-1)*2}%。`}</p><p class="tiny">${f.level>=5?'設施已達上限':materialText(c.cost)+'<br>憑證 '+c.credits}</p><button ${f.level>=5||!afford(c.cost,c.credits)?'disabled':''} onclick="upgradeBase('${id}')">${f.level>=5?'已滿級':'升級設施'}</button></section>`}).join('')}</div><div class="sectionhead"><h2>製造 · 收容與招募共用裝置</h2><span class="tiny muted">純遊戲資源，沒有付費抽取</span></div><div class="craft-grid">${Object.entries(devices).map(([t,d])=>`<section class="panel device tier-${t}"><div class="ball-illustration">◉</div><h3>${d.name}</h3><p class="tiny muted">庫存 ${W().balls[t]} 顆 · 捕獲率額外 +${Math.round(d.bonus*100)}%<br>${materialText(d.cost)} / 憑證 ${d.credits}</p><button ${W().base.workshop.level<t||!afford(d.cost,d.credits)?'disabled':''} onclick="craftBall(${t})">${W().base.workshop.level<t?'技術台 Lv.'+t+' 解鎖':'製造 1 顆'}</button></section>`).join('')}</div><p class="tiny muted">T1 / T2 / T3 材料與裝置是此同人遊戲自訂系統。幹員、敵人使用既有角色與素材。</p>`};
window.rosterView=function(){let count=Object.keys(W().roster).length;$('#app').innerHTML=`<div class="eyebrow">PERSONNEL / CONTAINMENT ARCHIVE</div><div class="sectionhead"><h1>每次相遇，都有可能留下。</h1><span class="badge">${count}/${Object.keys(units).length}</span></div><p class="muted intro">幹員透過野外信號招募，敵人先削弱再收容；撤離後才正式入庫。重複獲得會增加信賴碎片。可訓練至 Lv.5，選 1 位支援或 1 位駐站人員。</p>${materialBar()}<div class="roster-grid">${Object.entries(units).filter(([id,d])=>d.kind==='operator').map(([id,d])=>{let u=W().roster[id],cost=u?trainingCost(id):null,seen=!!W().seen[id];return `<article class="panel unit-card ${u?'owned':seen?'seen':'unknown'}"><span class="unit-rarity">${d.kind==='operator'?'★'.repeat(d.rarity):'敵方 · '+d.rarity+' 級'}</span>${img(id,'roster-image')}<h3>${seen?d.name:'未識別目標'}</h3><p class="tiny muted">${unitProgress(id)}</p><p class="tiny">${d.kind==='operator'?`支援：出發加入「${cards[d.card].name}」${u&&u.level>=3?'＋':''}。`:`支援：每場初始格擋 +${u?2+u.level:3}。`}</p>${u?`<div class="row"><button class="small" onclick="assignUnit('${id}','companion')">${W().companion===id?'✓ 出勤支援':'設為支援'}</button><button class="small" onclick="assignUnit('${id}','worker')">${W().worker===id?'✓ 駐站生產':'設為駐站'}</button></div><div class="divider"></div><p class="tiny muted">${u.level>=5?'已達 Lv.5':`訓練：${materialText(cost.cost)} / 憑證 ${cost.credits}${u.shards?'（消耗 1 碎片，憑證折半）':''}`}</p><button class="full" ${u.level>=5||!afford(cost.cost,cost.credits)?'disabled':''} onclick="trainUnit('${id}')">${u.level>=5?'培育完成':'訓練升級'}</button>`:`<span class="tag">${seen?'已發現，等待撤離帶回':'遠征中尋找'}</span>`}${d.wiki?`<a class="wiki-link" href="https://prts.wiki/w/${encodeURIComponent(d.wiki)}" target="_blank" rel="noopener">PRTS 資料 ↗</a>`:''}</article>`}).join('')}</div>`};
function trainingCost(id){let u=W().roster[id];return{cost:{scrap:4*u.level,alloy:u.level>=2?u.level:0,core:u.level>=4?1:0},credits:Math.ceil(10*u.level*(u.shards?.5:1))}}
window.trainUnit=function(id){let u=W().roster[id];if(!u||u.level>=5)return;let c=trainingCost(id);if(!spend(c.cost,c.credits)){toast('訓練材料不足。');return}if(u.shards)u.shards--;u.level++;save();render();toast(units[id].name+' 升到 Lv.'+u.level)};
window.assignUnit=function(id,slot){if(!W().roster[id]||!['companion','worker'].includes(slot))return;if(slot==='worker')claimBase();W()[slot]=id;save();render();toast(slot==='worker'?'駐站已調整，下輪產出生效。':'支援已選擇，下次出勤生效。')};
function offers(){let day=W().shop.day,seed=[...day].reduce((a,c)=>a*31+c.charCodeAt(0),7)>>>0;return [{id:'scrap',type:'material',key:'scrap',qty:8,currency:'credits',cost:12,limit:3},{id:'alloy',type:'material',key:'alloy',qty:3,currency:'credits',cost:15,limit:3},{id:'core',type:'material',key:'core',qty:1,currency:'credits',cost:22+seed%9,limit:2},{id:'ball1',type:'ball',key:1,qty:2,currency:'scrap',cost:5,limit:3},{id:'ball2',type:'ball',key:2,qty:1,currency:'alloy',cost:2,limit:2},{id:'daily',type:'ball',key:seed%3+1,qty:1,currency:'credits',cost:[8,16,30][seed%3],limit:1}]}
window.shopView=function(){syncShop();let next=Date.parse(W().shop.day+'T00:00:00+08:00')+DAY;$('#app').innerHTML=`<div class="eyebrow">TRADING POST / ${W().shop.day}</div><h1>補缺、出貨，再出發。</h1><p class="muted">每日台北時間 00:00 更新商品與限購次數，距下次 ${clockText(next-Date.now())}。本地單機存檔，不跨裝置同步時鐘。</p>${materialBar()}<div class="shop-grid">${offers().map(o=>{let n=W().shop.bought[o.id]||0,name=o.type==='material'?mats[o.key].name:devices[o.key].name,money=o.currency==='credits'?'憑證':mats[o.currency].name,can=n<o.limit&&(o.currency==='credits'?db.credits>=o.cost:W().materials[o.currency]>=o.cost);return `<section class="panel"><span class="tag">${o.id==='daily'?'今日輪替':'限量補給'}</span><h3>${name} ×${o.qty}</h3><p class="muted tiny">${money} ${o.cost} · 今日 ${n}/${o.limit}</p><button ${!can?'disabled':''} onclick="buyOffer('${o.id}')">${n>=o.limit?'今日售罄':'購買'}</button></section>`}).join('')}</div><div class="sectionhead"><h2>出售材料與庫存</h2><span class="tiny muted">賣價低於買價</span></div><section class="panel">${Object.entries(mats).map(([id,m])=>`<div class="trade-row"><span>${m.name} · 庫存 ${W().materials[id]}</span><button ${W().materials[id]<1?'disabled':''} onclick="sellMaterial('${id}')">出售 1 份 · +${m.sell}</button></div>`).join('')}${relics.filter(x=>x.id!=='compass').map(x=>`<div class="trade-row"><span>${x.icon} ${x.name} · 庫存 ${db.stock[x.id]||0}</span><button ${!(db.stock[x.id]>0)?'disabled':''} onclick="sellRelic('${x.id}')">出售 1 件 · +${Math.floor(x.value/2)}</button></div>`).join('')}<p class="tiny muted">出售不抹去圖鑑紀錄。原始羅盤為配發品，無法出售。</p></section>`};
window.buyOffer=function(id){syncShop();let o=offers().find(o=>o.id===id);if(!o)return;let n=W().shop.bought[id]||0;if(n>=o.limit)return;if(o.currency==='credits'){if(db.credits<o.cost)return;db.credits-=o.cost}else{if(W().materials[o.currency]<o.cost)return;W().materials[o.currency]-=o.cost}if(o.type==='material')W().materials[o.key]+=o.qty;else W().balls[o.key]+=o.qty;W().shop.bought[id]=n+1;save();render();toast('商品已入庫。')};
window.sellMaterial=function(id){if(!mats[id]||W().materials[id]<1)return;W().materials[id]--;db.credits+=mats[id].sell;save();render()};
window.sellRelic=function(id){let x=rget(id);if(!x||id==='compass'||!(db.stock[id]>0))return;modal('出售 '+x.name+'？',`<p>出售 1 件可得 ${Math.floor(x.value/2)} 憑證，圖鑑仍保留。</p>`,`<button class="primary" onclick="closeModal();confirmSellRelic('${id}')">確認出售</button><button onclick="closeModal()">取消</button>`)};
window.confirmSellRelic=function(id){let x=rget(id);if(!x||id==='compass'||!(db.stock[id]>0))return;db.stock[id]--;db.credits+=Math.floor(x.value/2);save();render()};
nav=function(){$('#nav').innerHTML=[['home','⌂','羅德島'],['run','⌁','遠征'],['base','▧','基建'],['roster','◉','幹員／敵人'],['collection','◇','倉庫'],['shop','▤','商店']].map(([p,i,t])=>`<button class="${page===p?'active':''}" onclick="go('${p}')"><span>${i}</span>${t}</button>`).join('')};
render=function(){ensure();if(page==='base'){nav();document.querySelector('body').classList.remove('in-battle');baseView()}else if(page==='roster'){nav();document.querySelector('body').classList.remove('in-battle');rosterView()}else if(page==='shop'){nav();document.querySelector('body').classList.remove('in-battle');shopView()}else originals.render()};
home=function(){originals.home();$('#app').innerHTML+=`<section class="panel home-base"><div><div class="eyebrow">CAPTURE / CRAFT / CULTIVATE</div><h3>基地正在運轉。</h3><p class="muted tiny">收菜製球、遠征捕獲、撤離入庫。現有 ${Object.keys(W().roster).length} 種單位，裝置 ${Object.values(W().balls).reduce((a,b)=>a+b,0)} 顆。</p></div><div class="row"><button class="primary" onclick="go('base')">前往基建</button><button onclick="go('roster')">培育圖鑑</button><button onclick="go('archive')">存檔</button></div></section>`};
prepare=function(){originals.prepare();let div=document.createElement('section');div.className='panel capture-loadout';div.innerHTML=`<div class="eyebrow">CAPTURE LOADOUT</div><h3>帶哪些收容球出發？</h3><p class="tiny muted">最多攜帶 6 顆；安全撤離歸還未使用裝置，戰敗與緊急撤出會遺失。製造、購買後才能補充。未攜帶也能正常戰鬥。</p><div class="load-balls">${Object.entries(devices).map(([t,d])=>`<label class="tier-${t}">${d.name}<small>庫存 ${W().balls[t]}</small><select id="ball-load-${t}" aria-label="攜帶 T${t} 球數量">${Array.from({length:Math.min(6,W().balls[t])+1},(_,n)=>`<option value="${n}" ${n===Math.min(W().balls[t],t==='1'?3:t==='2'?1:0)?'selected':''}>${n} 顆</option>`).join('')}</select></label>`).join('')}</div><p class="tiny muted">支援：${units[W().companion].name} Lv.${W().roster[W().companion].level} · ${units[W().companion].kind==='operator'?'加入專屬牌':'每場增加起始格擋'}</p><button onclick="go('base')">製球與收菜</button> <button onclick="go('roster')">更換支援</button>`;let app=$('#app'),buttons=app.lastElementChild;app.insertBefore(div,buttons)};
startRun=function(){let load={};for(let t of [1,2,3])load[t]=Math.max(0,Math.min(W().balls[t],Number($('#ball-load-'+t)?.value||0)));if(Object.values(load).reduce((a,b)=>a+b,0)>6){toast('收容球最多帶 6 顆。');return}if(R()&&!R().result)return;originals.startRun();ensure();for(let t of [1,2,3]){W().balls[t]-=load[t];F().balls[t]=load[t]}R().choices=['search','battle','event'];let id=F().companion,u=units[id],owned=W().roster[id];if(u.kind==='operator')R().deck.push({id:u.card,up:owned.level>=3});save();render()};
locations.signal=['◉','陌生幹員信號','野外招募 · 消耗裝置邀請'];
function rollMaterials(t){}
completeNode=function(){let r=R();if(!r||r.result)return;let step=r.step;originals.completeNode();if(r.result)return;save();render()};
enter=function(t){originals.enter(t==='signal'?'search':t)};
found=function(id){rollMaterials(R().node==='search'?'search':R().node==='elite'?'elite':'battle');originals.found(id)};
function captureSize(){return F()?.cargo.length*2||0}
bagSize=function(){return originals.bagSize()+captureSize()};
bagHtml=function(){let html=originals.bagHtml();if(!F())return html;let f=F();return html+`<section class="panel field-cargo"><h3>材料與捕獲</h3><p class="tiny muted">材料：${materialText(f.materials)}<br>安全撤離帶回全部；失敗只保留 25%。材料不佔背包格。</p><p class="tiny">裝置：${[1,2,3].map(t=>`T${t} ×${f.balls[t]}`).join(' / ')}</p>${f.cargo.map((id,i)=>`<div class="capture-cargo">${img(id)}<div><b>${units[id].name}</b><small>待撤離 · 2 格</small></div><button class="small" ${R().secure||f.securedCapture?'disabled':''} onclick="secureCapture(${i})">保險</button><button class="small" onclick="releaseCapture(${i})">釋放</button></div>`).join('')}${f.securedCapture?`<div class="secure-slot">${img(f.securedCapture)}<b>保險收容：${units[f.securedCapture].name}</b><p class="tiny muted">戰敗也能帶回；與遺物共用 1 個保險名額。</p><button class="small" onclick="unsecureCapture()">移回背包</button></div>`:''}</section>`};
const oldSecureItem=secureItem;secureItem=function(i){if(F()?.securedCapture){toast('保險袋已保護一個捕獲單位。');return}oldSecureItem(i)};
const oldTakeLoot=takeLoot;takeLoot=function(s){if(s&&F()?.securedCapture){toast('保險名額已使用。');return}oldTakeLoot(s)};
window.secureCapture=function(i){let f=F(),r=R();if(r.battle||r.reward||r.secure||f.securedCapture||!f.cargo[i])return;f.securedCapture=f.cargo.splice(i,1)[0];save();render()};
window.unsecureCapture=function(){let f=F();if(!f.securedCapture||R().battle||R().reward)return;if(bagSize()+2>capacity()){toast('背包需要空出 2 格。');return}f.cargo.push(f.securedCapture);f.securedCapture=null;save();render()};
window.releaseCapture=function(i){let r=R(),f=F();if(r.battle||r.reward||!f.cargo[i])return;modal('釋放 '+units[f.cargo[i]].name+'？','<p>只保留發現紀錄，本趟不再帶回此單位。</p>',`<button class="danger" onclick="closeModal();confirmRelease(${i})">確認釋放</button><button onclick="closeModal()">取消</button>`)};
window.confirmRelease=function(i){if(!F()?.cargo[i])return;F().cargo.splice(i,1);save();render()};
function transformEnemies(b){b.enemies.forEach((e,i)=>{if(e.species)return;let pool=b.type==='elite'?['enemy_1006_shield','enemy_1003_ncbow']:R().step<2?['enemy_1007_slime','enemy_1000_gopro','enemy_1002_nsabr']:enemyIds.filter(id=>id!=='enemy_1500_skulsr');let id=e.boss?'enemy_1500_skulsr':pick(pool);e.species=id;e.name=units[id].name;e.captureTries=0;W().seen[id]=true;if(id==='enemy_1006_shield')e.block=5;if(id==='enemy_1000_gopro'){e.atk+=1;e.hp=Math.max(10,e.hp-3);e.max=e.hp}if(id==='enemy_1005_yokai'){e.atk=0;e.intent='buff'}})}
startBattle=function(t,pending){originals.startBattle(t,pending);ensure();transformEnemies(R().battle);let c=F().companion;if(units[c]?.kind==='enemy')R().battle.block+=2+W().roster[c].level;save();render()};
battleView=function(){let b=R().battle;if(b)transformEnemies(b);originals.battleView();if(!b)return;let buttons=$('#app').querySelectorAll('.enemy-card');b.enemies.forEach((e,i)=>{let figure=buttons[i]?.querySelector('.enemy-figure');if(figure&&e.species)figure.innerHTML=img(e.species,'enemy-art')});let panel=document.createElement('details');panel.className='capture-toolbar';let living=b.enemies.filter(e=>e.hp>0);panel.innerHTML=`<summary>◉ 嘗試收容 · 削弱提高機率 · 1 能量</summary><div class="row between"><div><b>◉ 收容機會</b><p class="tiny muted">削弱提高機率。一次消耗 1 能量、1 顆球；失敗本回合仍可出牌。</p></div><button class="small" onclick="captureRules()">機率說明</button></div><div class="capture-targets">${living.map(e=>`<div><b>${e.name}</b><small>生命 ${e.hp}/${e.max} · 警戒與戰鬥仍會繼續</small><div class="row">${[1,2,3].map(t=>`<button class="small tier-${t}" ${!F().balls[t]||b.energy<1||bagSize()+2>capacity()?'disabled':''} onclick="throwAtEnemy('${e.id}',${t})">T${t} ${Math.round(chance(e.species,t,e.hp/e.max)*100)}% (${F().balls[t]})</button>`).join('')}</div></div>`).join('')}</div>${bagSize()+2>capacity()?'<p class="tiny muted">背包不足 2 格，先在區域畫面整理，或擊敗目標。</p>':''}`;let battle=$('#app').querySelector('.card-battle'),hand=battle.querySelector('.hand-caption');battle.insertBefore(panel,hand)};
function chance(id,t,hp=1){let u=units[id],base=u.kind==='operator'?({3:.42,4:.28,5:.2,6:.1}[u.rarity]||.42):({1:.38,2:.28,3:.18,4:.08}[u.rarity]||.2);return Math.min(.95,Math.max(.05,base+(1-hp)*.42+devices[t].bonus+tune('captureBonus',0)+(R()?.captureDrugBonus||0)+(W().base.workshop.level-1)*.02+Math.min(.15,(W().pity[id]||0)*.03)))}
window.captureRules=function(){modal('捕獲與招募機率','<p>顯示的是本次實際成功率，最高 95%，不保證成功。T2 / T3 相對 T1 額外 +18% / +38%；技術台每升一級 +2%。敵人剩餘生命越低，額外加成越高，最多 +42%。</p><p>對同一種類失敗會累積安撫加成，每次 +3%，最多 +15%，成功即重置。幹員不需要戰鬥，招募事件最多嘗試 3 次。所有裝置均用免費遊戲材料製造或交換。</p><p>成功只代表現場同行／收容。每個單位佔 2 格，安全撤離才正式入庫。可以用共用保險名額保護 1 個單位。</p>','<button class="primary full" onclick="closeModal()">知道了</button>')};
function attempt(id,t,hp){if(!devices[t]||!F()?.balls[t]||bagSize()+2>capacity())return null;F().balls[t]--;let p=chance(id,t,hp),success=random()<p;R().captureDrugBonus=0;W().pity[id]=success?0:(W().pity[id]||0)+1;if(success)F().cargo.push(id);save();return{success,p}}
window.throwAtEnemy=function(enemyId,t){let b=R()?.battle,e=b?.enemies.find(e=>e.id===enemyId&&e.hp>0);if(!e||b.energy<1||!F().balls[t]||bagSize()+2>capacity())return;let result=attempt(e.species,t,e.hp/e.max);if(!result)return;b.energy--;selected=null;if(result.success){e.hp=0;e.captured=true;log('收容成功：'+e.name+'（仍需撤離）')}else log('收容失敗：'+e.name+' 掙脫裝置。');if(checkBattle()){toast(result.success?'收容成功，單位在背包等待撤離。':'收容失敗。');if(result.success)revealCapture(e.species);return}save();render();toast(result.success?'收容成功！佔用 2 格。':'掙脫了，安撫加成已累積。');if(result.success)revealCapture(e.species)};
eventView=function(){let e=R().event;if(e?.type!=='signal'){originals.eventView();return}let u=units[e.id];$('#app').innerHTML=runHeader()+`<div class="layout"><section class="panel recruit-event"><div class="eyebrow">FIELD RECRUITMENT / ${e.tries}/3 ATTEMPTS</div>${img(e.id,'recruit-portrait')}<span class="tag">${'★'.repeat(u.rarity)} · 幹員信號</span><h2>${u.name}，正在等待應答。</h2><p class="muted">消耗一顆裝置發出招募邀請。這是相遇時的邀請，不是強制捕獲。最多三次，接受後佔背包 2 格。</p><div class="row">${[1,2,3].map(t=>`<button class="tier-${t}" ${e.tries>=3||!F().balls[t]||bagSize()+2>capacity()?'disabled':''} onclick="recruitTry(${t})">T${t} · ${Math.round(chance(e.id,t)*100)}% · 剩 ${F().balls[t]}</button>`).join('')}</div><p class="tiny muted">本次信號抽選：芬／玫蘭莎／克洛絲各 4/19，潔西卡／調香師各 3/19，能天使 1/19。機率與裝置成功率分開計算。</p><button class="primary" onclick="completeNode()">${e.tries>=3?'道別，繼續行動':'暫不邀請，繼續探索'}</button><button onclick="captureRules()">機率說明</button></section><aside>${bagHtml()}</aside></div>`};
window.recruitTry=function(t){let e=R()?.event;if(e?.type!=='signal'||e.tries>=3)return;let a=attempt(e.id,t,1);if(!a){toast('裝置不足，或背包需要空出 2 格。');return}e.tries++;if(a.success){let name=units[e.id].name;completeNode();toast(name+' 接受邀請！成功撤離後正式加入。');revealCapture(e.id)}else{save();render();toast('這次沒有得到肯定回應，安撫加成已增加。')}};
window.revealCapture=function(id){let u=units[id];modal(u.kind==='operator'?'招募回應已收到':'收容成功',`<div class="capture-reveal"><span class="eyebrow">${u.kind==='operator'?'NEW CONNECTION':'CONTAINMENT SECURED'}</span>${img(id,'reveal-image')}<span class="tag">${u.kind==='operator'?'★'.repeat(u.rarity):'敵方樣本 · '+u.rarity+' 級'}</span><h2>${u.name}</h2><p class="muted tiny">${R()?.result?'此單位已完成本趟結算。':'已加入現場背包，佔用 2 格。<br>成功撤離才能正式入庫，也能放入保險袋保護。'}</p></div>`,'<button class="primary full" onclick="closeModal()">確認紀錄 →</button>')};
function receiveUnit(id){let r=W().roster[id];if(r){r.copies++;r.shards++}else W().roster[id]={level:1,copies:1,shards:0};W().seen[id]=true}
endRun=function(result,index=-1){let r=R();if(!r||r.result)return;let f=F(),safe=['extract','win'].includes(result);if(f&&!f.settled){let kept=safe?[...f.cargo]:[];if(f.securedCapture)kept.push(f.securedCapture);kept.forEach(receiveUnit);let acquired={};for(let k of Object.keys(mats)){let n=safe?f.materials[k]:Math.floor(f.materials[k]*.25);W().materials[k]+=n;acquired[k]=n}if(safe)for(let t of [1,2,3])W().balls[t]+=f.balls[t];f.settled=true;f.summary={kept,materials:acquired,lost:f.cargo.length+(f.securedCapture?1:0)-kept.length,returnedBalls:safe?{...f.balls}:{1:0,2:0,3:0}}}originals.endRun(result,index);save()};
finishView=function(){originals.finishView();let s=F()?.summary;if(!s)return;$('#app').innerHTML+=`<section class="panel extraction-summary"><div class="eyebrow">NEW ADDITIONS / EXTRACTED</div><h3>材料與同行者已結算</h3><p>${materialText(s.materials)}</p><div class="captured-summary">${s.kept.map(id=>`<div>${img(id)}<b>${units[id].name}</b><small>${unitProgress(id)}</small></div>`).join('')||'<p class="muted tiny">本趟沒有帶回新單位。</p>'}</div><p class="tiny muted">未帶回捕獲 ${s.lost} 位 · 歸還裝置 ${Object.values(s.returnedBalls).reduce((a,b)=>a+b,0)} 顆。</p><button onclick="go('roster')">查看培育圖鑑</button><button onclick="go('base')">前往基建</button></section>`};
const oldRetreat=retreat;retreat=function(){let r=R();if(r.battle||r.event||r.reward||![2,4].includes(r.step))return;modal('把收穫帶回羅德島？',`<p>安全帶回 ${r.bag.length} 件遺物、${F().cargo.length+(F().securedCapture?1:0)} 位單位、全部材料與未用裝置。攜行遺物也會歸還。</p>`,'<button class="primary" onclick="closeModal();endRun(\'extract\')">確認撤離</button><button onclick="closeModal()">繼續深入</button>')};
const oldEmergency=emergency;emergency=function(){if(F()?.cargo.length||F()?.securedCapture){toast('緊急撤出只保留保險收容；其他捕獲會遺失。')}oldEmergency()};
collection=function(){originals.collection();$('#app').innerHTML=`<div class="row between"><span class="tag">遺物倉庫</span><button onclick="go('roster')">幹員與敵人圖鑑 →</button></div>`+$('#app').innerHTML};
archive=function(){originals.archive();$('#app').innerHTML+=`<section class="panel" style="margin-top:20px"><h3>基地、捕獲與商店</h3><p class="tiny muted">完整存檔包含基建時間、材料、球、單位培育與每日限購。離線生產以裝置時間推進，單機版本不提供跨裝置同步。</p><button onclick="go('base')">回到基地</button></section>`};
sources=function(){originals.sources();let p=document.createElement('p');p.innerHTML='<a href="https://prts.wiki/w/首页" target="_blank" rel="noopener">PRTS 方舟百科 ↗</a><br>七種敵人名稱、身分參考；圖片沿用公開遊戲素材庫。卡牌數值、捕獲、材料等級、基建與市場規則為本同人原型自訂，並非明日方舟原作機制。';$('#modal').insertBefore(p,$('#modal').lastElementChild)};
help=function(){originals.help();let p=document.createElement('p');p.innerHTML='<b>新增：收菜、製球與捕獲</b><br>基建最多累積 48 小時產出。T1／T2／T3 球可用於幹員邀請與敵人收容。戰鬥收容花 1 能量，削弱生命會提高成功率。每個捕獲佔 2 格；撤離才正式入庫，保險名額可保 1 位。球最多帶 6 顆，安全撤離歸還未使用裝置；失敗會遺失。材料不佔格子，失敗帶回 25%。每日商店台北時間 00:00 換日，無付費抽取。';$('#modal').insertBefore(p,$('#modal').lastElementChild)};
validSave=function(v){if(!originals.validSave(v))return false;let w=v.world;if(!w)return true;let n=x=>Number.isInteger(x)&&x>=0,counts=o=>o&&typeof o==='object'&&Object.values(o).every(n);if(w.version!==1||!counts(w.materials)||!Object.keys(mats).every(k=>n(w.materials[k]))||!counts(w.balls)||![1,2,3].every(t=>n(w.balls[t]))||!w.base||!Object.keys(facilities3).every(k=>n(w.base[k]?.level)&&w.base[k].level>=1&&w.base[k].level<=5&&Number.isFinite(w.base[k].last))||!w.roster||!Object.entries(w.roster).every(([id,u])=>units[id]&&n(u.level)&&u.level>=1&&u.level<=5&&n(u.copies)&&n(u.shards))||!w.roster[w.companion]||(w.worker!=null&&!w.roster[w.worker])||!w.seen||!w.shop||!/^\d{4}-\d{2}-\d{2}$|^$/.test(w.shop.day)||!counts(w.shop.bought)||!counts(w.pity))return false;let f=v.run?.field;if(!f)return true;if(!counts(f.balls)||![1,2,3].every(t=>n(f.balls[t]))||!Array.isArray(f.cargo)||!f.cargo.every(id=>units[id])||!counts(f.materials)||!Object.keys(mats).every(k=>n(f.materials[k]))||f.securedCapture!=null&&!units[f.securedCapture]||!units[f.companion]||typeof f.settled!=='boolean')return false;return true};
// Allow the new encounter type through the existing version-2 save validator.
const priorValidate=validSave;validSave=function(v){if(v?.run?.event?.type==='signal'){let e=v.run.event;if(!units[e.id]||units[e.id].kind!=='operator'||!Number.isInteger(e.tries)||e.tries<0||e.tries>3)return false;let copy={...v,run:{...v.run,event:null}};return priorValidate(copy)}return priorValidate(v)};
confirmImport=function(){originals.confirmImport();ensure();save();render()};
const validateWorld=validSave;validSave=function(v){if(!validateWorld(v))return false;let f=v.run?.field,b=v.run?.battle,w=v.world;if(b&&!b.enemies.every(e=>!e.species||units[e.species]?.kind==='enemy'))return false;if(f&&(!w?.roster[f.companion]||f.settled&&(!f.summary||!Array.isArray(f.summary.kept)||!f.summary.kept.every(id=>units[id])||!f.summary.materials||!Object.keys(mats).every(k=>Number.isInteger(f.summary.materials[k])&&f.summary.materials[k]>=0)||!Number.isInteger(f.summary.lost)||f.summary.lost<0||![1,2,3].every(t=>Number.isInteger(f.summary.returnedBalls?.[t])&&f.summary.returnedBalls[t]>=0))))return false;return true};
checkBattle=function(){let b=R()?.battle;if(b&&b.type==='boss'&&!b.materialAward&&R().hp>0&&b.enemies.every(e=>e.hp<=0)){b.materialAward=true;rollMaterials('boss')}return originals.checkBattle()};
// Expose deterministic rules for focused engine checks; no production shortcuts.
window.FrontierCapture={units,mats,devices,pending,chance,dayKey,offers,ensure,materialText};
const validateBeforeRng=validSave;validSave=function(v){return (!v.testing||window.FrontierStorage?.profile==='developer')&&(!v.tuning||Object.entries(v.tuning).every(([k,n])=>{const limits={noDurability:[0,1],energy:[1,10],draw:[1,10],health:[1,9999],damageMultiplier:[.1,10],offlineHours:[1,72],captureBonus:[-.8,.8]};return limits[k]&&Number.isFinite(n)&&n>=limits[k][0]&&n<=limits[k][1]}))&&validateBeforeRng(v)&&(!v.rng||!window.FrontierRandom||FrontierRandom.valid(v.rng))};
// Saved cards must exist before the bootstrap validator, including an unfinished new-rule raid.
Object.assign(cards,{field_silence:{name:'靜默干擾',owner:'common',cost:1,kind:'attack',damage:3,silence:1,text:'造成3物理傷害並沉默，可破解特殊行動。',rulesVersion:2},field_break:{name:'破甲標定',owner:'common',cost:1,kind:'attack',damage:4,armorBreak:2,mark:true,text:'造成4物理傷害並標記；防禦降低2，持續2回合。',rulesVersion:2},field_disrupt:{name:'頻段清除',owner:'common',cost:1,kind:'attack',damage:3,dispel:true,text:'造成3物理傷害，移除敵方增益或干擾屏障。',rulesVersion:2},curio_tactic:{name:'臨時戰術指令',owner:'common',cost:0,kind:'tactic',exhaust:true,text:'選擇造成3點傷害或獲得3點護盾；本回合有效。',rulesVersion:2},field_guard:{name:'協同防護',owner:'common',cost:1,kind:'block',block:6,exhaust:false,text:'生命比例最低的存活隊員獲得6點護盾。',rulesVersion:2},field_draw:{name:'戰術整備',owner:'common',cost:1,kind:'draw',draw:2,activeDiscard:1,exhaust:false,text:'抽2張牌，主動棄置1張。',rulesVersion:2}});
for(const id of ['field_silence','field_break','field_disrupt'])if(!specialPool.includes(id))specialPool.push(id);
if(!window.FrontierSaveGuard.validate(v=>{const type=v?.run?.event?.type;return validSave(['sealedContainer','fieldMerchant','frontierEvent'].includes(type)?{...v,run:{...v.run,event:null}}:v)}))return;
if(window.FrontierRandom)FrontierRandom.ensure(db);
ensure();if(!window.FrontierStorage)save();render();
if(typeof setInterval==='function')setInterval(()=>{if(page==='base'||page==='shop')render()},60000);
